33	/// How to emit whitespace.
34	#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash)]
35	pub enum Whitespace {
36	    /// Ensures that whitespace that would otherwise be collapsed by HTML
37	    /// rendering engines[^1] is protected by spans with `white-space:
38	    /// pre-wrap`. The affected by whitespace are ASCII spaces and ASCII tabs.
39	    ///
40	    /// Tries to emit spans only when necessary.
41	    /// - ASCII tabs and consecutive sequences of spaces and/or tabs are always
42	    ///   wrapped in spans in this mode. This happens directly during
43	    ///   conversion.
44	    /// - Single ASCII spaces are only wrapped if they aren't supported by
45	    ///   normal elements on both sides. This happens in a separate pass that
46	    ///   runs for the whole block-level context as doing this properly needs
47	    ///   lookahead and lookbehind across different levels of the element
48	    ///   hierarchy.
49	    ///
50	    /// [^1]: <https://www.w3.org/TR/css-text-3/#white-space-rules>
51	    Normal,
52	    /// The whitespace is emitted as-is. This happens in
53	    /// - `<pre>` elements as they already have `white-space: pre`,
54	    /// - raw and escapable raw text elements as normal white space rules do not
55	    ///   apply to them.
56	    Pre,
57	}
58	
59	/// Converts realized content into HTML nodes.
60	pub fn convert_to_nodes<'a>(
61	    engine: &mut Engine,
62	    locator: &mut SplitLocator,
63	    children: impl IntoIterator<Item = Pair<'a>>,
64	    level: ConversionLevel,
65	    whitespace: Whitespace,
66	) -> SourceResult<EcoVec<HtmlNode>> {
67	    let block = matches!(level, ConversionLevel::Block);
68	    let mut converter = Converter {
69	        engine,
70	        locator,
71	        quoter: match level {
72	            ConversionLevel::Inline(quoter) => quoter,
73	            ConversionLevel::Block => &mut SmartQuoter::new(),
74	        },
75	        whitespace,
76	        output: EcoVec::new(),
77	        trailing: None,
78	    };
79	
80	    for (child, styles) in children {
81	        handle(&mut converter, child, styles)?;
82	    }
83	
84	    let mut nodes = converter.finish();
85	    if block && whitespace == Whitespace::Normal {
86	        protect_spaces(&mut nodes);
87	    }
88	
89	    Ok(nodes)
90	}
91	
92	/// Converts one element into HTML node(s).
93	fn handle(
94	    converter: &mut Converter,
95	    child: &Content,
96	    styles: StyleChain,
97	) -> SourceResult<()> {
98	    if let Some(elem) = child.to_packed::<TagElem>() {
99	        converter.push(elem.tag.clone());
100	    } else if let Some(elem) = child.to_packed::<HtmlElem>() {
101	        handle_html_elem(converter, elem, styles)?;
102	    } else if child.is::<SpaceElem>() {
103	        converter.push(HtmlNode::text(' ', child.span()));
104	    } else if let Some(elem) = child.to_packed::<TextElem>() {
105	        let text = if let Some(case) = styles.get(TextElem::case) {
106	            case.apply(&elem.text).into()
107	        } else {
108	            elem.text.clone()
109	        };
110	        handle_text(converter, text, elem.span());
111	    } else if let Some(elem) = child.to_packed::<HElem>()
112	        && elem.amount.is_zero()
113	    {
114	        // Nothing to do for zero-sized spacing. This is sometimes used to
115	        // destruct spaces, e.g. in footnotes. See [`HElem::hole`].
116	    } else if let Some(elem) = child.to_packed::<LinebreakElem>() {
117	        converter.push(match converter.whitespace {
118	            Whitespace::Normal => HtmlElement::new(tag::br).spanned(elem.span()).into(),
119	            Whitespace::Pre => HtmlNode::text("\n", elem.span()),
120	        });
121	    } else if let Some(elem) = child.to_packed::<SmartQuoteElem>() {
122	        let double = elem.double.get(styles);
123	        let quote = if elem.enabled.get(styles) {
124	            let before = last_char(&converter.output);
125	            let quotes = SmartQuotes::get(
126	                elem.quotes.get_ref(styles),
127	                styles.get(TextElem::lang),
128	                styles.get(TextElem::region),
129	                elem.alternative.get(styles),
130	            );
131	            converter.quoter.quote(before, &quotes, double)
132	        } else {
133	            SmartQuotes::fallback(double)
134	        };
135	        handle_text(converter, quote.into(), child.span());
136	    } else if let Some(elem) = child.to_packed::<BoxElem>() {
137	        handle_box(converter, elem, styles)?;
138	    } else if let Some(elem) = child.to_packed::<BlockElem>() {
139	        handle_block(converter, elem, styles)?;
140	    } else if let Some(elem) = child.to_packed::<FrameElem>() {
141	        let locator = converter.locator.next(&elem.span());
142	        let style = TargetElem::target.set(Target::Paged).wrap();
143	        let frame = (converter.engine.library.routines.layout_frame)(
144	            converter.engine,
145	            &elem.body,
146	            locator,
147	            styles.chain(&style),
148	            Region::new(Size::splat(Abs::inf()), Axes::splat(false)),
149	        )?;
150	        let mut node = HtmlFrame::new(frame, styles, elem.span()).into();
151	        // A frame is block-level by default like a Typst `image`. It can
152	        // be wrapped in a `box` to omit the `display` annotation.
153	        make_block_level(&mut node).unwrap();
154	        converter.push(node);
155	    } else {
156	        converter.engine.sink.warn(warning!(
157	            child.span(),
158	            "{} was ignored during HTML export",
159	            child.elem().name(),
160	        ));
161	    }
162	    Ok(())
163	}
164	
165	/// Handles an HTML element.
166	fn handle_html_elem(
167	    converter: &mut Converter,
168	    elem: &Packed<HtmlElem>,
169	    styles: StyleChain,
170	) -> SourceResult<()> {
171	    // See the docs of `HtmlElem::role` for why we filter out roles for `<p>`
172	    // elements.
173	    let role = styles.get_cloned(HtmlElem::role).filter(|_| elem.tag != tag::p);
174	
175	    let mut children = EcoVec::new();
176	    if let Some(body) = elem.body.get_ref(styles) {
177	        let whitespace = if converter.whitespace == Whitespace::Pre
178	            || elem.tag == tag::pre
179	            || tag::is_raw(elem.tag)
180	            || tag::is_escapable_raw(elem.tag)
181	        {
182	            Whitespace::Pre
183	        } else {
184	            Whitespace::Normal
185	        };
186	
187	        // The `role` attribute should only apply to the first element in the
188	        // hierarchy. Thus, we unset it for children if it is currently set.
189	        let unset;
190	        let styles = if role.is_some() {
191	            unset = HtmlElem::role.set(None).wrap();
192	            styles.chain(&unset)
193	        } else {
194	            styles
195	        };
196	
197	        if property::Display::default_for(elem.tag) == Some(property::Display::Block) {
198	            children = html_block_fragment(
199	                converter.engine,
200	                body,
201	                converter.locator.next(&elem.span()),
202	                styles,
203	                whitespace,
204	            )?;
205	
206	            // Block-level elements reset the inline state. This part is
207	            // unfortunately untested as it's currently not possible to
208	            // create inline-level content next to block-level content
209	            // without a paragraph automatically appearing.
210	            *converter.quoter = SmartQuoter::new();
211	        } else if tag::mathml::is_mathml(elem.tag) {
212	            children = html_math_fragment(
213	                converter.engine,
214	                body,
215	                converter.locator,
216	                converter.quoter,
217	                styles,
218	                whitespace,
219	            )?;
220	        } else {
221	            children = html_inline_fragment(
222	                converter.engine,
223	                body,
224	                converter.locator,
225	                converter.quoter,
226	                styles,
227	                whitespace,
228	            )?;
229	        }
230	    }
231	
232	    let mut attrs = elem.attrs.get_cloned(styles);
233	    if let Some(role) = role {
234	        attrs.push(attr::role, role);
235	    }
236	
237	    converter.push(HtmlElement {
238	        tag: elem.tag,
239	        attrs,
240	        css: elem.css.get_cloned(styles),
241	        children,
242	        parent: elem.parent,
243	        span: elem.span(),
244	        pre_span: false,
245	    });
246	
247	    Ok(())
248	}
249	
250	/// Handles arbitrary text while taking care that no whitespace within will be
251	/// collapsed by browsers.
252	fn handle_text(converter: &mut Converter, text: EcoString, span: Span) {
253	    /// Special kinds of characters.
254	    #[derive(Debug, Copy, Clone, Eq, PartialEq)]
255	    enum Kind {
256	        /// ASCII space.
257	        Space,
258	        /// ASCII tab.
259	        Tab,
260	        /// CR, LF, or CR + LF.
261	        Newline,
262	        /// A Unicode default-ignorable. Does not protect spaces from
263	        /// collapsing.
264	        Ignorable,
265	    }
266	
267	    impl Kind {
268	        fn of(c: char) -> Option<Kind> {
269	            match c {
270	                ' ' => Some(Kind::Space),
271	                '\t' => Some(Kind::Tab),
272	                '\r' | '\n' => Some(Kind::Newline),
273	                c if is_default_ignorable(c) => Some(Kind::Ignorable),
274	                _ => None,
275	            }
276	        }
277	    }
278	
279	    if converter.whitespace == Whitespace::Pre {
280	        converter.push(HtmlNode::Text(text, span));
281	        return;
282	    }
283	
284	    let mut emitted = 0;
285	    let mut prev_kind = None;
286	
287	    for (i, c) in text.char_indices() {
288	        let kind = Kind::of(c);
289	        let prev_kind = prev_kind.replace(kind);
290	        let Some(kind) = kind else { continue };
291	
292	        // A space that is surrounded by normal (i.e. not special) characters is
293	        // already protected and doesn't need further treatment.
294	        if kind == Kind::Space
295	            && let Some(None) = prev_kind
296	            && let Some(after) = text[i + 1..].chars().next()
297	            && Kind::of(after).is_none()
298	        {
299	            continue;
300	        }
301	
302	        // Emit the unspecial text up to the special character.
303	        if emitted < i {
304	            converter.push_text(&text[emitted..i], span);
305	            emitted = i;
306	        }
307	
308	        // Process the special character.
309	        match kind {
310	            Kind::Space => converter.push_text(' ', span),
311	            Kind::Tab => converter.push_text('\t', span),
312	            Kind::Newline => {
313	                if c == '\r' && text[i + 1..].starts_with('\n') {
314	                    // Skip the CR because the LF will already turn into
315	                    // a `<br>`.
316	                    emitted += 1;
317	                    continue;
318	                }
319	                converter.push(HtmlElement::new(tag::br).spanned(span));
320	            }
321	            Kind::Ignorable => converter.push_text(c, span),
322	        }
323	        emitted += c.len_utf8();
324	    }
325	
326	    // Push the remaining unspecial text.
327	    if emitted < text.len() {
328	        converter.push_text(
329	            // Try to reuse the `EcoString` if possible.
330	            if emitted == 0 { text } else { text[emitted..].into() },
331	            span,
332	        );
333	    }
334	}
335	
336	/// Processes a box element.
337	fn handle_box(
338	    converter: &mut Converter,
339	    elem: &Packed<BoxElem>,
340	    styles: StyleChain,
341	) -> SourceResult<()> {
342	    let mut children = EcoVec::new();
343	    if let Some(body) = elem.body.get_ref(styles) {
344	        children = html_inline_fragment(
345	            converter.engine,
346	            body,
347	            converter.locator,
348	            converter.quoter,
349	            styles,
350	            converter.whitespace,
351	        )?;
352	
353	        if let Some(node) = to_lone_element(&mut children) {
354	            make_inline_level(node);
355	            converter.extend(children);
356	            return Ok(());
357	        }
358	    }
359	
360	    converter.push(
361	        // TODO: This is rather incomplete.
362	        HtmlElement::new(tag::span)
363	            .with_css(css::Properties::new().with("display", "inline-block"))
364	            .with_children(children)
365	            .spanned(elem.span()),
366	    );
367	
368	    Ok(())
369	}
370	
371	/// Ensures a lone HTML element/frame renders inline.
372	///
373	/// Paragraphs only allow "Phrasing content". The default display properties
374	/// that exists for valid phrasing content are `none`, `inline`, `inline-block`,
375	/// `contents`, `ruby`, and `inline math`. These can all be left as-is.
376	///
377	/// If, however, the `display` property was set to something like `block`
378	/// through a Typst `block` element, we need to unset it. Further, if a math
379	/// element has its `display` attribute set to `block`, then we need to
380	/// override it.
381	fn make_inline_level(node: &mut HtmlNode) {
382	    let mode = if let HtmlNode::Element(element) = node
383	        && element.tag == tag::mathml::math
384	        && element.attrs.get(attr::mathml::display).is_some_and(|v| v == "block")
385	    {
386	        Some(property::Display::InlineMath)
387	    } else {
388	        None
389	    };
390	    set_display(node, mode);
391	}
392	
393	/// Processes a block element.
394	fn handle_block(
395	    converter: &mut Converter,
396	    elem: &Packed<BlockElem>,
397	    styles: StyleChain,
398	) -> SourceResult<()> {
399	    let body = match elem.body.get_ref(styles) {
400	        None => None,
401	        Some(BlockBody::Content(body)) => Some(body),
402	        // These are only generated by native `typst-layout` show rules.
403	        Some(BlockBody::SingleLayouter(_) | BlockBody::MultiLayouter(_)) => {
404	            bail!(
405	                elem.span(),
406	                "blocks with layout routines should not occur in \
407	                 HTML export – this is a bug";
408	            )
409	        }
410	    };
411	
412	    let mut children = EcoVec::new();
413	    if let Some(body) = body {
414	        children = html_block_fragment(
415	            converter.engine,
416	            body,
417	            converter.locator.next(&elem.span()),
418	            styles,
419	            converter.whitespace,
420	        )?;
421	
422	        if let Some(node) = to_lone_element(&mut children)
423	            && make_block_level(node).is_ok()
424	        {
425	            converter.extend(children);
426	            return Ok(());
427	        }
428	    }
429	
430	    converter.push(
431	        // TODO: This is rather incomplete.
432	        HtmlElement::new(tag::div)
433	            .with_children(children)
434	            .spanned(elem.span()),
435	    );
436	
437	    Ok(())
438	}
