440	/// Ensures a lone HTML element/frame renders as its own block.
441	///
442	/// Configures the `display` property of the HTML node (if it is an element or
443	/// frame).
444	fn make_block_level(node: &mut HtmlNode) -> Result<(), Unblockable> {
445	    let default = match node {
446	        // A math element's default display property depends on its `display`
447	        // attribute.
448	        HtmlNode::Element(element)
449	            if element.tag == tag::mathml::math
450	                && element
451	                    .attrs
452	                    .get(attr::mathml::display)
453	                    .is_some_and(|v| v == "block") =>
454	        {
455	            Some(property::Display::BlockMath)
456	        }
457	        HtmlNode::Element(element) => property::Display::default_for(element.tag),
458	        HtmlNode::Frame(_) => Some(property::Display::Inline),
459	        _ => return Err(Unblockable),
460	    };
461	
462	    let mode = match default {
463	        // These can be left unchanged / have `display` unset because they are
464	        // either invisible or already render in a block-level way.
465	        Some(
466	            property::Display::None
467	            | property::Display::Block
468	            | property::Display::Table
469	            | property::Display::ListItem
470	            | property::Display::Contents
471	            | property::Display::BlockMath,
472	        ) => None,
473	
474	        // These must be promoted to `block`.
475	        None | Some(property::Display::Inline | property::Display::InlineBlock) => {
476	            Some(property::Display::Block)
477	        }
478	        Some(property::Display::InlineMath) => Some(property::Display::BlockMath),
479	
480	        // These can't be promoted. They are instead wrapped in a `<div>`.
481	        _ => return Err(Unblockable),
482	    };
483	
484	    set_display(node, mode);
485	    Ok(())
486	}
487	
488	/// Indicates that an element can be made block-level with a `display` property.
489	#[derive(Debug, Copy, Clone)]
490	struct Unblockable;
491	
492	/// Whether, apart from tags, the nodes comprise a single element or frame.
493	fn to_lone_element(nodes: &mut EcoVec<HtmlNode>) -> Option<&mut HtmlNode> {
494	    let (start, end) = nodes.split_prefix_suffix(|node| matches!(node, HtmlNode::Tag(_)));
495	    matches!(&nodes[start..end], [HtmlNode::Element(_) | HtmlNode::Frame(_)])
496	        .then(|| &mut nodes.make_mut()[start])
497	}
498	
499	/// Sets the CSS `display` property for an element or frame.
500	fn set_display(node: &mut HtmlNode, display: Option<property::Display>) {
501	    let css = match node {
502	        HtmlNode::Element(element) => &mut element.css,
503	        HtmlNode::Frame(frame) => &mut frame.css,
504	        _ => return,
505	    };
506	    match display {
507	        Some(display) => css.push("display", display.as_str()),
508	        None => css.remove("display"),
509	    }
510	}
511	
512	/// State during conversion.
513	struct Converter<'a, 'y, 'z> {
514	    engine: &'a mut Engine<'y>,
515	    locator: &'a mut SplitLocator<'z>,
516	    quoter: &'a mut SmartQuoter,
517	    whitespace: Whitespace,
518	    output: EcoVec<HtmlNode>,
519	    trailing: Option<TrailingWhitespace>,
520	}
521	
522	/// Keeps track of a trailing whitespace in the output.
523	struct TrailingWhitespace {
524	    /// If `true`, the trailing whitespace consists of exactly one ASCII space.
525	    single: bool,
526	    /// The trailing whitespace starts at `output[from..]`.
527	    from: usize,
528	}
529	
530	impl Converter<'_, '_, '_> {
531	    /// Returns the converted nodes.
532	    fn finish(mut self) -> EcoVec<HtmlNode> {
533	        self.flush_whitespace();
534	        self.output
535	    }
536	
537	    /// Pushes a node, taking care to protect consecutive whitespace.
538	    fn push(&mut self, node: impl Into<HtmlNode>) {
539	        let node = node.into();
540	
541	        if let HtmlNode::Text(text, _) = &node
542	            && (text == " " || text == "\t")
543	        {
544	            if let Some(ws) = &mut self.trailing {
545	                ws.single = false;
546	            } else {
547	                self.trailing = Some(TrailingWhitespace {
548	                    single: text == " ",
549	                    from: self.output.len(),
550	                });
551	            }
552	        } else if !matches!(node, HtmlNode::Tag(_)) {
553	            self.flush_whitespace();
554	        }
555	
556	        self.output.push(node);
557	    }
558	
559	    /// Pushes multiples nodes.
560	    fn extend(&mut self, nodes: impl IntoIterator<Item = HtmlNode>) {
561	        for node in nodes {
562	            self.push(node);
563	        }
564	    }
565	
566	    /// Shorthand for pushing a text node.
567	    fn push_text(&mut self, text: impl Into<EcoString>, span: Span) {
568	        self.push(HtmlNode::text(text.into(), span));
569	    }
570	
571	    /// If there is trailing whitespace in need of protection, protects it.
572	    ///
573	    /// Does not protect single ASCII spaces. Those are handled in a separate
574	    /// pass as they are more complex and require lookahead. See the
575	    /// documentation of [`Whitespace`] for more information.
576	    fn flush_whitespace(&mut self) {
577	        if self.whitespace == Whitespace::Normal
578	            && let Some(TrailingWhitespace { single: false, from }) = self.trailing.take()
579	        {
580	            let nodes: EcoVec<_> = self.output[from..].iter().cloned().collect();
581	            self.output.truncate(from);
582	            self.output.push(HtmlNode::Element(pre_wrap(nodes)));
583	        }
584	    }
585	}
586	
587	/// Protects all spaces in the given block-level `nodes` against collapsing.
588	///
589	/// Does not recurse into block-level elements as those are separate contexts
590	/// with their own space protection.
591	fn protect_spaces(nodes: &mut EcoVec<HtmlNode>) {
592	    let mut p = Protector::new();
593	    p.visit_nodes(nodes);
594	    p.collapsing();
595	}
596	
597	/// A state machine for whitespace protection.
598	enum Protector<'a> {
599	    Collapsing,
600	    Supportive,
601	    Space(&'a mut HtmlNode),
602	}
603	
604	impl<'a> Protector<'a> {
605	    /// Creates a new protector.
606	    fn new() -> Self {
607	        Self::Collapsing
608	    }
609	
610	    /// Visits the given nodes and protects single spaces that need to be saved
611	    /// from collapsing.
612	    fn visit_nodes(&mut self, nodes: &'a mut EcoVec<HtmlNode>) {
613	        for node in nodes.make_mut().iter_mut() {
614	            match node {
615	                HtmlNode::Tag(_) => {}
616	                HtmlNode::Text(text, _) => {
617	                    if text == " " {
618	                        match self {
619	                            Self::Collapsing => {
620	                                protect_space(node);
621	                                *self = Self::Supportive;
622	                            }
623	                            Self::Supportive => {
624	                                *self = Self::Space(node);
625	                            }
626	                            Self::Space(prev) => {
627	                                protect_space(prev);
628	                                *self = Self::Space(node);
629	                            }
630	                        }
631	                    } else if text.chars().any(|c| !is_default_ignorable(c)) {
632	                        self.supportive();
633	                    }
634	                }
635	                HtmlNode::Element(element) => {
636	                    if tag::is_whitespace_collapsing(element.tag) {
637	                        self.collapsing();
638	                    } else if tag::is_replaced(element.tag) {
639	                        self.supportive();
640	                    } else if !element.pre_span {
641	                        // Recursively visit the children of inline-level
642	                        // elements while making sure to not revisit pre-wrapped
643	                        // spans that we've generated ourselves.
644	                        self.visit_nodes(&mut element.children);
645	                    }
646	                }
647	                HtmlNode::Frame(_) => self.supportive(),
648	            }
649	        }
650	    }
651	
652	    /// Called when visiting an element that would collapse adjacent single
653	    /// spaces. A preceding, if any, and succeeding, if any, single space will
654	    /// then be protected .
655	    fn collapsing(&mut self) {
656	        if let Self::Space(node) = std::mem::replace(self, Self::Collapsing) {
657	            protect_space(node);
658	        }
659	    }
660	
661	    /// Called when visiting an element that supports adjacent single spaces.
662	    fn supportive(&mut self) {
663	        *self = Self::Supportive;
664	    }
665	}
666	
667	/// Protects a single spaces against collapsing.
668	fn protect_space(node: &mut HtmlNode) {
669	    *node = pre_wrap(eco_vec![node.clone()]).into();
670	}
671	
672	/// Wraps a collection of whitespace nodes in a
673	/// `<span style="white-space: pre-wrap">..</span>` to avoid them being
674	/// collapsed by HTML rendering engines.
675	fn pre_wrap(nodes: EcoVec<HtmlNode>) -> HtmlElement {
676	    let span = Span::find(nodes.iter().map(|c| c.span()));
677	    let mut elem = HtmlElement::new(tag::span)
678	        .with_css(css::Properties::new().with("white-space", "pre-wrap"))
679	        .with_children(nodes)
680	        .spanned(span);
681	    elem.pre_span = true;
682	    elem
683	}
684	
685	/// Returns the last non-default ignorable character from the passed nodes.
686	fn last_char(nodes: &[HtmlNode]) -> Option<char> {
687	    for node in nodes.iter().rev() {
688	        if let Some(c) = match node {
689	            HtmlNode::Text(s, _) => s.chars().rev().find(|&c| !is_default_ignorable(c)),
690	            HtmlNode::Element(e) => last_char(&e.children),
691	            _ => None,
692	        } {
693	            return Some(c);
694	        }
695	    }
696	    None
697	}
